BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L2 — Corporate gain recognition on appreciated property distribution
(3, 'C Corporations', 'Redwood Corp distributes equipment with a fair market value of $95,000 and an adjusted basis of $60,000 to its sole shareholder as a dividend. What gain does Redwood Corp recognize on the distribution?', '["$35,000 gain", "$95,000 gain", "$60,000 gain", "$0 — no gain on distributions to shareholders"]'::jsonb, 0, 'Under IRC Section 311(b), a corporation recognizes gain on the distribution of appreciated property as if the property were sold at its fair market value. The gain is $95,000 FMV minus $60,000 basis, or $35,000. Choice D is incorrect because Section 311(b) specifically overrides the general nonrecognition rule when the distributed property has appreciated in value.', 'easy', 2),

-- Q2: hard / L4 — Section 246A DRD reduction for debt-financed portfolio stock
(3, 'C Corporations', 'Thornberry Corp owns 10% of Linden Corp, purchased entirely with borrowed funds. Thornberry receives $200,000 in dividends from Linden. Thornberry''s average indebtedness on the Linden stock is 100% of its adjusted basis. Evaluate how Section 246A affects Thornberry''s dividends received deduction.', '["The DRD remains at 50% because Section 246A only applies to 80%-or-more ownership", "The DRD is reduced to $0 because the stock is entirely debt-financed", "The DRD is disallowed entirely under Section 265 as interest on tax-exempt income", "The DRD is reduced proportionally — the 50% DRD is multiplied by the debt-financed percentage, eliminating it entirely"]'::jsonb, 1, 'Under IRC Section 246A, when portfolio stock (less than 50% ownership) is debt-financed, the DRD is reduced proportionally by the average indebtedness percentage. At 100% debt financing, the 50% DRD is multiplied by (1 minus 100%), reducing it to $0. Choice A is incorrect because Section 246A applies to less-than-50% ownership, not 80%-or-more ownership where the 100% DRD applies.', 'hard', 4),

-- Q3: medium / L3 — Section 362(e)(2) loss duplication rule
(3, 'C Corporations', 'Franklin transfers land with an adjusted basis of $300,000 and a fair market value of $180,000 to Cypress Corp for 100% of the stock in a qualifying Section 351 exchange. Franklin does not make a Section 362(e)(2)(C) election. Analyze how Cypress Corp''s basis in the land compares to Franklin''s stock basis.', '["Both Cypress and Franklin take a $300,000 basis", "Cypress takes a $300,000 basis in the land while Franklin takes a $180,000 basis in the stock", "Both Cypress and Franklin take a $180,000 basis", "Cypress takes a $180,000 basis in the land while Franklin takes a $300,000 basis in the stock"]'::jsonb, 3, 'Under IRC Section 362(e)(2), when property transferred in a Section 351 exchange has a built-in loss (basis exceeds FMV), the corporation''s basis is limited to the property''s FMV of $180,000 to prevent loss duplication. However, the transferor''s stock basis under Section 358 remains $300,000 (the substituted basis). Choice A is incorrect because Section 362(e)(2) specifically prevents both parties from claiming the built-in loss.', 'medium', 3),

-- Q4: hard / L4 — Accumulated taxable income computation for AET
(3, 'C Corporations', 'Granite Corp has taxable income of $800,000, federal income tax of $168,000, a dividends received deduction of $30,000, charitable contributions of $25,000, and pays $100,000 in dividends. Granite''s accumulated earnings credit is $250,000. Evaluate Granite''s accumulated taxable income subject to the accumulated earnings tax.', '["$257,000", "$532,000", "$282,000", "$632,000"]'::jsonb, 2, 'Under IRC Section 535, accumulated taxable income equals taxable income ($800,000) minus federal income tax ($168,000), minus the dividends paid deduction ($100,000), minus the accumulated earnings credit ($250,000), yielding $282,000. The DRD and charitable contributions are already reflected in taxable income and are not subtracted again. Choice A ($257,000) is incorrect because it improperly subtracts the charitable contributions a second time from the accumulated taxable income computation.', 'hard', 4),

-- Q5: easy / L1 — Section 1202 QSBS exclusion
(3, 'C Corporations', 'What is the maximum percentage of gain that may be excluded under Section 1202 for qualified small business stock acquired after September 27, 2010?', '["100%", "75%", "50%", "60%"]'::jsonb, 0, 'Under IRC Section 1202(a)(4), shareholders who hold qualified small business stock (QSBS) acquired after September 27, 2010, for more than five years may exclude 100% of the gain on sale, subject to the greater-of limitation ($10 million or 10 times basis). Choice C (50%) is incorrect because that exclusion percentage applies only to QSBS acquired before February 18, 2009.', 'easy', 1),

-- Q6: medium / L2 — Corporate charitable contribution of ordinary income property
(3, 'C Corporations', 'Sequoia Corp donates inventory with a fair market value of $200,000 and a cost basis of $130,000 to a qualified 501(c)(3) public charity. The inventory is not qualified food donations and will not be used for the care of the ill or needy. What is Sequoia Corp''s charitable contribution deduction?', '["$130,000", "$200,000", "$165,000", "$70,000"]'::jsonb, 0, 'Under IRC Section 170(e)(1)(A), when a C corporation donates ordinary income property (inventory) that does not qualify for the enhanced deduction exceptions (care of ill/needy, food donations), the deduction is limited to the property''s adjusted basis of $130,000 — the FMV reduced by the ordinary income that would have been recognized on sale. Choice B ($200,000) is incorrect because the full FMV deduction applies only to long-term capital gain property donated to public charities.', 'medium', 2),

-- Q7: hard / L4 — Corporate AMT (CAMT) under Inflation Reduction Act
(3, 'C Corporations', 'Ironbridge Holdings, a publicly traded C corporation, reports average annual adjusted financial statement income (AFSI) of $1.2 billion over the prior three tax years. Its regular tax liability for 2026 is $180 million, and its tentative minimum tax under the corporate alternative minimum tax is $195 million. Evaluate Ironbridge''s total federal income tax liability.', '["$180 million", "$375 million", "$15 million", "$195 million"]'::jsonb, 3, 'Under IRC Section 55 as amended by the Inflation Reduction Act of 2022, applicable corporations (AFSI exceeding $1 billion over three years) pay the greater of their regular tax or the 15% corporate AMT (CAMT). Since the tentative minimum tax of $195 million exceeds the regular tax of $180 million, Ironbridge owes $195 million total — not both amounts combined. Choice B ($375 million) is incorrect because the CAMT replaces the regular tax when higher, not in addition to it.', 'hard', 4),

-- Q8: medium / L2 — E&P effect of stock redemption treated as distribution
(3, 'C Corporations', 'Magnolia Corp has accumulated E&P of $400,000. Magnolia redeems 200 shares from shareholder Collins for $150,000. The redemption does not qualify for exchange treatment under Section 302(b) and is treated as a Section 301 distribution. How does the $150,000 redemption affect Magnolia''s E&P?', '["E&P is not affected because redemptions are capital transactions", "E&P is increased by $150,000 because the corporation received treasury stock", "E&P is reduced by $150,000, the amount of the distribution treated as a dividend", "E&P is reduced by the pro rata share of E&P attributable to the redeemed shares"]'::jsonb, 2, 'Under IRC Section 312(a), when a stock redemption is treated as a Section 301 distribution rather than an exchange, E&P is reduced by the amount of the distribution to the extent it constitutes a dividend — here, $150,000 from accumulated E&P. Choice D is incorrect because the pro rata E&P reduction rule under Section 312(n)(7) applies only when the redemption qualifies as an exchange under Section 302(b).', 'medium', 2),

-- Q9: medium / L2 — Schedule M-1 adjustment for officer life insurance premiums
(3, 'C Corporations', 'Birchfield Corp reports $700,000 of net income per books. The books include $18,000 of life insurance premiums on the CEO where the corporation is the beneficiary, $12,000 of tax-exempt municipal bond interest, and $35,000 of federal income tax expense. What is Birchfield Corp''s taxable income per Schedule M-1?', '["$723,000", "$741,000", "$735,000", "$665,000"]'::jsonb, 1, 'Schedule M-1 reconciles book income to taxable income. Starting with book income of $700,000, add back the nondeductible officer life insurance premiums ($18,000) and federal income tax ($35,000), then subtract the tax-exempt municipal bond interest ($12,000): $700,000 + $18,000 + $35,000 - $12,000 = $741,000. Choice A ($723,000) is incorrect because it omits the add-back for nondeductible life insurance premiums, which under IRC Section 264(a)(1) are not deductible when the corporation is the policy beneficiary.', 'medium', 2),

-- Q10: medium / L2 — Section 351 with services contributor failing control test
(3, 'C Corporations', 'Harper contributes equipment (basis $90,000, FMV $150,000) for 60% of Ashland Corp''s stock, and Torres contributes consulting services valued at $100,000 for 40% of the stock. What gain does Harper recognize on the exchange?', '["$0", "$150,000", "$90,000", "$60,000"]'::jsonb, 3, 'Under IRC Section 351, the exchange is tax-free only if transferors of property control (80%) the corporation immediately after the transfer. Torres contributed services, not property, so Torres does not count toward the control group. Harper owns only 60%, failing the 80% control requirement, so Section 351 does not apply. Harper recognizes the full $60,000 realized gain ($150,000 FMV minus $90,000 basis). Choice A ($0) is incorrect because it assumes Section 351 applies, but the control test is not met.', 'medium', 2),

-- Q11: medium / L3 — Thin capitalization reclassification effect on interest deductions
(3, 'C Corporations', 'Westlake Corp has a debt-to-equity ratio of 8:1. The IRS reclassifies $600,000 of Westlake''s purported debt as equity. Westlake had been deducting $42,000 of annual interest on the reclassified amount. Analyze the effect of the reclassification on Westlake''s taxable income and shareholder treatment.', '["Westlake retains the interest deduction, but payments are reclassified as return of capital", "Westlake loses the $42,000 interest deduction, and the payments are treated as nondeductible dividends", "Westlake loses the interest deduction, and the payments are treated as deductible compensation", "Westlake retains the interest deduction because only the principal is reclassified"]'::jsonb, 1, 'Under IRC Section 385 and related case law, when debt is reclassified as equity, interest payments become nondeductible dividend distributions. Westlake loses the $42,000 deduction, increasing taxable income, and the shareholder must report the payments as dividends rather than interest income. Choice D is incorrect because reclassification affects the character of all payments — both principal repayments and interest — converting them to equity distributions.', 'medium', 3),

-- Q12: easy / L1 — Definition of E&P
(3, 'C Corporations', 'What is the purpose of earnings and profits (E&P) in C corporation taxation?', '["To measure the corporation''s economic capacity to pay dividends and determine the tax treatment of distributions", "To calculate the corporation''s taxable income for Form 1120", "To determine the corporation''s eligibility for the dividends received deduction", "To compute the corporation''s accumulated earnings tax credit"]'::jsonb, 0, 'Under IRC Section 316, earnings and profits measure a corporation''s economic ability to distribute dividends. E&P determines whether distributions to shareholders are taxed as dividends, return of capital, or capital gain under the Section 301 ordering rules. Choice B is incorrect because taxable income is computed independently on Form 1120 — E&P is a separate concept that starts with taxable income but includes additional adjustments.', 'easy', 1),

-- Q13: medium / L2 — Charitable contribution carryforward with 10% limitation
(3, 'C Corporations', 'Ashworth Corp has taxable income of $800,000 before the charitable deduction and DRD for 2026. Ashworth makes $100,000 in charitable contributions and has a $15,000 charitable carryforward from 2025. What is Ashworth''s allowable charitable deduction for 2026?', '["$100,000, with $15,000 carried forward", "$80,000, with $35,000 carried forward", "$115,000", "$95,000, with $20,000 carried forward"]'::jsonb, 1, 'Under IRC Section 170(b)(2), a C corporation''s charitable deduction is limited to 10% of taxable income computed before the charitable deduction, DRD, NOL carryback, and capital loss carryback. The limit is $800,000 x 10% = $80,000. The current-year contributions ($100,000) are applied first, with only $80,000 deductible. The $15,000 carryforward cannot be used, and $20,000 of current-year excess plus $15,000 carryforward ($35,000) carry forward. Choice C ($115,000) is incorrect because the 10% ceiling applies regardless of available carryforwards.', 'medium', 2),

-- Q14: medium / L3 — E&P adjustment for installment sale
(3, 'C Corporations', 'Hillcrest Corp sells land (basis $120,000, FMV $300,000) on an installment basis in 2026, receiving $100,000 in the first year. Hillcrest reports $60,000 of installment gain on its tax return. Analyze how this transaction affects Hillcrest''s current E&P differently than its taxable income.', '["E&P matches taxable income and includes only the $60,000 installment gain", "E&P includes only the $100,000 cash received, ignoring the gain computation", "E&P includes the full $180,000 gain in the year of sale, not just the $60,000 reported for tax purposes", "E&P excludes the gain entirely until all payments are received"]'::jsonb, 2, 'Under IRC Section 312, E&P does not follow the installment method. The full $180,000 gain ($300,000 FMV minus $120,000 basis) is included in E&P in the year of sale, even though only $60,000 is reported for tax purposes under the installment method. This is a common E&P adjustment tested on the CPA exam. Choice A is incorrect because E&P uses the accrual method and recognizes the entire economic gain immediately.', 'medium', 3),

-- Q15: easy / L1 — Prohibited corporate deductions
(3, 'C Corporations', 'Which of the following expenses is nondeductible for a C corporation under the Internal Revenue Code?', '["Employee salaries and wages", "Rent expense for office space", "Depreciation on business equipment", "Penalties and fines paid to a government agency"]'::jsonb, 3, 'Under IRC Section 162(f), penalties and fines paid to a government for violations of law are not deductible as business expenses. This prohibition applies to both civil and criminal penalties. Choice A is incorrect because reasonable salaries and wages are deductible ordinary and necessary business expenses under Section 162(a).', 'easy', 1),

-- Q16: easy / L1 — Corporate tax rate under TCJA
(3, 'C Corporations', 'What is the federal income tax rate for C corporations under the Tax Cuts and Jobs Act?', '["A graduated rate from 15% to 35%", "A flat rate of 28%", "A flat rate of 21%", "A flat rate of 15%"]'::jsonb, 2, 'Under IRC Section 11(b) as amended by the TCJA (2017), all C corporations are taxed at a single flat rate of 21% on taxable income, effective for tax years beginning after December 31, 2017. Choice A is incorrect because the graduated rate structure (15%, 25%, 34%, 35%) was eliminated by the TCJA and replaced with the flat 21% rate.', 'easy', 1),

-- Q17: hard / L4 — Section 269 acquisition to evade taxes
(3, 'C Corporations', 'Prescott Industries acquires 100% of Talbot Corp, which has $4 million in NOL carryforwards but minimal business operations. Prescott''s board minutes state the acquisition''s principal purpose is utilizing Talbot''s NOLs against Prescott''s $6 million annual profits. Evaluate the IRS''s strongest basis for challenging this transaction beyond Section 382.', '["Section 382 is the IRS''s only tool, limiting but not disallowing the NOLs", "Section 269 allows the IRS to disallow the NOL deduction entirely if the principal purpose of the acquisition was tax avoidance", "The step transaction doctrine would collapse the acquisition and eliminate the NOLs", "Section 482 allows reallocation of income between the two corporations"]'::jsonb, 1, 'Under IRC Section 269, if any person acquires control of a corporation and the principal purpose is to evade or avoid federal income tax by securing a deduction not otherwise available, the IRS may disallow the deduction entirely. Unlike Section 382, which merely limits annual NOL usage, Section 269 can eliminate the benefit completely. Choice A is incorrect because Section 382 imposes only a rate limitation — Section 269 provides an independent basis for complete disallowance when tax avoidance is the principal purpose.', 'hard', 4),

-- Q18: easy / L1 — Stock ownership test for PHC
(3, 'C Corporations', 'Under Section 542, what stock ownership percentage must five or fewer individuals hold for a corporation to meet the personal holding company stock ownership test?', '["More than 50% of the outstanding stock", "At least 80% of the outstanding stock", "At least 20% of the outstanding stock", "More than 35% of the outstanding stock"]'::jsonb, 0, 'Under IRC Section 542(a)(2), a corporation meets the PHC stock ownership test if more than 50% of the value of its outstanding stock is owned, directly or indirectly, by five or fewer individuals at any time during the last half of the tax year. Choice B (80%) is incorrect because that threshold applies to the Section 351 control test for tax-free incorporations, not the PHC ownership test.', 'easy', 1),

-- Q19: medium / L2 — E&P computation for nondeductible fines
(3, 'C Corporations', 'Ridgeway Corp has taxable income of $500,000 for 2026. In computing E&P, Ridgeway must account for $25,000 in nondeductible fines paid to a federal agency and $8,000 of tax-exempt municipal bond interest received. What is Ridgeway Corp''s current E&P before federal income tax adjustments?', '["$508,000", "$483,000", "$533,000", "$525,000"]'::jsonb, 1, 'Under IRC Section 312, E&P starts with taxable income and adjusts for items that affect economic capacity to pay dividends. Fines are already nondeductible for tax purposes, so they are not in taxable income — but they reduce E&P because they reduce economic resources: $500,000 - $25,000 + $8,000 = $483,000. Tax-exempt interest is added because it increases economic resources. Choice A ($508,000) is incorrect because it adds the fines instead of subtracting them from E&P.', 'medium', 2),

-- Q20: medium / L3 — Effect of Section 1059 on DRD for extraordinary dividends
(3, 'C Corporations', 'Trenton Corp owns 18% of Maplewood Corp and receives a $400,000 dividend. Trenton''s adjusted basis in the Maplewood stock is $1,500,000. The $400,000 dividend exceeds the 5% threshold for extraordinary dividends on common stock. Analyze how Section 1059 affects Trenton''s basis in the Maplewood stock.', '["Trenton''s basis is unaffected because Section 1059 applies only to 80%-or-more corporate shareholders", "Trenton must reduce its basis by the full $400,000 dividend amount", "Trenton must increase its basis by the taxed portion of the dividend ($200,000)", "Trenton must reduce its Maplewood stock basis by the nontaxed portion of the extraordinary dividend ($200,000)"]'::jsonb, 3, 'Under IRC Section 1059, when a corporate shareholder receives an extraordinary dividend (exceeding 5% of basis for common stock), it must reduce its stock basis by the nontaxed portion of the dividend. With an 18% ownership stake, Trenton claims a 50% DRD, so $200,000 is nontaxed. The stock basis is reduced by $200,000 to $1,300,000. Choice A is incorrect because Section 1059 applies to all corporate shareholders, not just those with 80%-or-more ownership.', 'medium', 3),

-- Q21: medium / L3 — Section 357(c) liability in excess of basis
(3, 'C Corporations', 'Hoffman transfers equipment with an adjusted basis of $75,000 and FMV of $250,000, subject to a $100,000 mortgage, to a newly formed corporation for 100% of the stock in a Section 351 exchange. Analyze the gain Hoffman recognizes and the resulting stock basis.', '["Hoffman recognizes $0 gain because the FMV exceeds the liability, and takes a $75,000 stock basis", "Hoffman recognizes $175,000 gain (the full difference between FMV and basis) and takes a $75,000 stock basis", "Hoffman recognizes $25,000 gain (liability exceeds basis by $25,000) and takes a $0 stock basis", "Hoffman recognizes $100,000 gain equal to the full mortgage amount and takes a $150,000 stock basis"]'::jsonb, 2, 'Under IRC Section 357(c), when liabilities assumed ($100,000) exceed the total adjusted basis of property transferred ($75,000) in a Section 351 exchange, the excess ($25,000) is recognized as gain. The stock basis is computed as $75,000 (property basis) minus $100,000 (liability) plus $25,000 (gain recognized) = $0. Choice A is incorrect because Section 357(c) triggers gain recognition regardless of the property''s FMV when liabilities exceed basis.', 'medium', 3),

-- Q22: easy / L1 — Tax year requirement for C corporations
(3, 'C Corporations', 'What tax year-end may a newly formed C corporation generally adopt without IRS approval?', '["Only a calendar year-end", "Only a fiscal year ending June 30 or December 31", "Only a natural business year-end", "Any fiscal year-end or a calendar year-end"]'::jsonb, 3, 'Under IRC Section 441, a C corporation (other than a personal service corporation) may generally adopt any fiscal year-end or a calendar year-end without IRS approval on its first filed return. This flexibility distinguishes C corporations from S corporations and personal service corporations, which face restrictions. Choice A is incorrect because the calendar-year requirement applies to S corporations and personal service corporations under Section 441(i) and Section 1378, not to regular C corporations.', 'easy', 1),

-- Q23: easy / L1 — Section 351 control threshold
(3, 'C Corporations', 'What is the minimum ownership percentage required under Section 351 for a tax-free incorporation?', '["80% of total voting power and 80% of all other classes of stock", "50% of total voting power", "51% of all outstanding shares", "Two-thirds of total voting power and value"]'::jsonb, 0, 'Under IRC Section 351(a) and Section 368(c), control for purposes of a tax-free incorporation means owning at least 80% of the total combined voting power of all classes of stock entitled to vote and at least 80% of the total number of shares of all other classes of stock. Choice B (50%) is incorrect because that is the threshold for the PHC stock ownership test, not the Section 351 control requirement.', 'easy', 1),

-- Q24: hard / L3 — Consolidated return intercompany transaction timing
(3, 'C Corporations', 'Atlas Corp and its 100%-owned subsidiary Beacon Corp file a consolidated return. Beacon sells depreciable equipment (basis $120,000) to Atlas for $200,000 in Year 1. Atlas depreciates the equipment over 5 years using straight-line depreciation. Analyze how much of Beacon''s $80,000 intercompany gain is recognized in the consolidated return in Year 2.', '["$80,000, recognized in full when the equipment is placed in service by Atlas", "$16,000, matching Atlas''s $16,000 excess depreciation over Beacon''s original basis", "$0, deferred until Atlas sells the equipment to a third party", "$40,000, recognized ratably over the 5-year depreciation period based on original gain"]'::jsonb, 1, 'Under Treasury Regulation Section 1.1502-13, intercompany gains are deferred and recognized as the buying member takes corresponding items (here, depreciation). Atlas depreciates on the $200,000 purchase price, but only the excess over Beacon''s $120,000 basis triggers gain recognition. Annual excess depreciation is ($200,000 - $120,000) / 5 = $16,000 per year. Choice C is incorrect because depreciation deductions are corresponding items that trigger partial annual recognition, not full deferral until disposition.', 'hard', 3),

-- Q25: medium / L2 — Section 1202 QSBS per-issuer gain limitation
(3, 'C Corporations', 'Nakamura purchases qualified small business stock in Cascade Tech Corp for $800,000 in 2020 and sells it in 2026 for $12,000,000 after holding it more than five years. Cascade Tech is a domestic C corporation with gross assets under $50 million. What is the maximum gain Nakamura may exclude under Section 1202?', '["$8,000,000", "$11,200,000", "$10,000,000", "$12,000,000"]'::jsonb, 2, 'Under IRC Section 1202(b), the excludable gain on QSBS is limited to the greater of $10,000,000 or 10 times the taxpayer''s adjusted basis ($800,000 x 10 = $8,000,000). Since $10,000,000 exceeds $8,000,000, the maximum exclusion is $10,000,000. The remaining $1,200,000 of gain is taxable. Choice A ($8,000,000) is incorrect because it uses only the 10-times-basis limitation without comparing it to the $10 million floor.', 'medium', 2),

-- Q26: medium / L3 — PHC income classification of adjusted rental income
(3, 'C Corporations', 'Cedarbrook Corp, a closely held C corporation, has adjusted ordinary gross income (AOGI) of $600,000 consisting of $350,000 in rental income (after adjustments) and $250,000 in dividends and interest. The rental income is 58.3% of AOGI. Analyze whether the rental income is classified as personal holding company income.', '["The rental income is excluded from PHC income because it equals or exceeds 50% of AOGI", "The rental income is included in PHC income because it is below 60% of AOGI", "The rental income is excluded from PHC income only if Cedarbrook distributes its nonrental PHC income", "The rental income is always classified as PHC income regardless of the AOGI percentage"]'::jsonb, 2, 'Under IRC Section 543(a)(2), adjusted rental income is excluded from PHC income if it constitutes 50% or more of AOGI — which it does at 58.3%. However, this exclusion requires an additional condition: the nonrental PHC income (dividends and interest of $250,000) must not exceed 10% of ordinary gross income, or the corporation must distribute this nonrental PHC income. Choice A is incorrect because it states the 50% threshold alone is sufficient without addressing the distribution requirement for nonrental PHC income.', 'medium', 3),

-- Q27: easy / L1 — Charitable contribution carryforward period for corporations
(3, 'C Corporations', 'How many years may a C corporation carry forward excess charitable contributions that exceed the 10% taxable income limitation?', '["10 years", "5 years", "20 years", "3 years"]'::jsonb, 1, 'Under IRC Section 170(d)(2), a C corporation may carry forward excess charitable contributions for 5 years. Contributions are applied on a first-in, first-out basis, with the oldest carryforward used before more recent excess amounts. Choice A (10 years) is incorrect because the 10-year carryforward period applies to individual taxpayers under certain circumstances, not to corporations.', 'easy', 1),

-- Q28: medium / L2 — Deficiency dividend procedure for PHC tax
(3, 'C Corporations', 'Sterling Corp is determined by the IRS to be a personal holding company for 2025 with $300,000 of undistributed PHC income. Sterling distributes $300,000 as a deficiency dividend within 90 days of the determination. What is the effect on Sterling''s PHC tax liability for 2025?', '["The PHC tax is eliminated with no additional interest or penalties", "The PHC tax is reduced by 50% of the deficiency dividend amount", "The deficiency dividend has no effect because it was not paid in the tax year at issue", "The PHC tax is eliminated, but Sterling must still pay interest and penalties on the late determination"]'::jsonb, 3, 'Under IRC Section 547, a corporation may claim a deduction for deficiency dividends paid within 90 days of a PHC tax determination, which eliminates the PHC tax liability. However, Sterling must still pay any applicable interest and penalties on the underlying tax deficiency from the original due date. Choice C is incorrect because Section 547 specifically allows retroactive treatment of deficiency dividends to reduce undistributed PHC income for the prior year.', 'medium', 2),

-- Q29: hard / L4 — S election risk factors: passive income penalty and BIG tax
(3, 'C Corporations', 'Pembrook Corp, a C corporation with $900,000 of accumulated E&P and built-in gain assets (FMV $2,500,000, basis $1,600,000), is considering an S election. Its projected income is 55% passive investment income. Evaluate the most critical risk Pembrook faces if it makes the S election.', '["The built-in gains tax will apply at 21% to all $900,000 of gains recognized within the five-year recognition period", "Pembrook cannot elect S status because its passive income exceeds 50% of gross receipts", "The S election will be automatically terminated after three consecutive years of passive income exceeding 25% of gross receipts while accumulated C corporation E&P exists", "The accumulated E&P will be immediately taxable to shareholders upon making the S election"]'::jsonb, 2, 'Under IRC Section 1362(d)(3), an S corporation''s election is automatically terminated if it has accumulated C corporation E&P and passive investment income exceeds 25% of gross receipts for three consecutive tax years. With 55% passive income and $900,000 of accumulated E&P, Pembrook faces involuntary termination — a more critical risk than the Section 1374 built-in gains tax. Choice A is incorrect because the BIG tax applies to asset appreciation at conversion, but election termination is the greater strategic threat since it forces reversion to C corporation status.', 'hard', 4),

-- Q30: medium / L3 — Effect of bonus depreciation on E&P vs taxable income
(3, 'C Corporations', 'Sycamore Corp places $500,000 of new 5-year MACRS equipment in service in 2026. Sycamore claims 60% first-year bonus depreciation ($300,000) plus regular MACRS on the remaining $200,000. For E&P purposes, Sycamore must use the alternative depreciation system. Analyze how the depreciation difference affects Sycamore''s E&P relative to taxable income in Year 1.', '["E&P will be lower than taxable income because E&P uses accelerated depreciation", "E&P will equal taxable income because bonus depreciation is allowed for both computations", "E&P will be higher than taxable income because E&P does not allow any depreciation deductions", "E&P will be higher than taxable income because E&P depreciation (ADS straight-line) is lower than the tax depreciation claimed"]'::jsonb, 3, 'Under IRC Section 312(k), E&P must use the alternative depreciation system (ADS), which requires straight-line depreciation over longer recovery periods and does not allow bonus depreciation. Since tax depreciation (bonus + MACRS) exceeds ADS depreciation, taxable income is lower than E&P in Year 1. Therefore, E&P is higher than taxable income. Choice B is incorrect because Section 312(k)(3)(A) specifically disallows bonus depreciation for E&P computation purposes.', 'medium', 3)
;

COMMIT;
